cd /home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/roadmap/items && python3 -c "
import yaml,glob,collections
items={}
for f in glob.glob('*.yaml'):
    d=yaml.safe_load(open(f))
    items[d['id']]=d
kids=collections.defaultdict(list)
for i,d in items.items():
    p=(d.get('metadata') or {}).get('parent') or d.get('parent')
    if p: kids[p].append(i)
OPEN={'pending','active','blocked'}
print('=== DONE PARENT WITH OPEN CHILDREN ===')
for p,ks in sorted(kids.items()):
    pd=items.get(p)
    if not pd: print('ORPHAN parent ref',p); continue
    if pd['status'] in ('done','rejected'):
        bad=[(k,items[k]['status']) for k in sorted(ks) if items[k]['status'] in OPEN]
        if bad: print(p,'('+pd['status']+')','->',bad)
print()
print('=== ALL CHILDREN DONE/REJECTED BUT PARENT OPEN ===')
for p,ks in sorted(kids.items()):
    pd=items.get(p)
    if not pd: continue
    if pd['status'] in OPEN:
        st=[items[k]['status'] for k in ks]
        if all(s in ('done','rejected') for s in st):
            print(p,'('+pd['status']+')','all',len(ks),'children done:',sorted(set(st)))
"
